:root{
  color-scheme:dark;--bg:#0b1118;--panel:#131e27;--panel2:#18252e;--line:#2b3b40;--muted:#91a19e;--text:#eef3e9;--mint:#b6edc4;--lime:#d8f487;--coral:#ff8676;--yellow:#f6cb70;--teal:#7ac4b0;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;min-height:100vh;overflow-x:hidden;background:radial-gradient(ellipse at 68% -12%,#34473b55,transparent 36%),radial-gradient(ellipse at 12% 45%,#15283265,transparent 42%),var(--bg);color:var(--text);font:14px var(--sans)}
body:before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.16'/%3E%3C/svg%3E")}
button{font:inherit}
.app-shell{max-width:1510px;margin:auto;padding:0 40px}
.topbar{height:74px;border-bottom:1px solid #29383a;display:flex;align-items:center;justify-content:space-between;position:relative}
.topbar:after{content:"";position:absolute;bottom:-1px;left:0;width:130px;height:1px;background:var(--lime);box-shadow:0 0 12px #d8f48755}
.brand{display:flex;gap:10px;align-items:center;text-decoration:none;color:var(--text);font:700 18px var(--display);letter-spacing:1.6px}
.brand-mark{font-size:25px;color:var(--lime);text-shadow:0 0 18px #d8f48777;animation:sigilDrift 5s ease-in-out infinite}
.brand-dot{color:var(--lime)}
.run-stamp,.eyebrow,.panel-title,.map-topline,.map-footer,.floor-badge,.sidebar-foot,.page-footer,.modal-kicker,.save-note,.howto,.stat-line,.operator-profile p,.depth-track{font-family:var(--mono);letter-spacing:1px}
.run-stamp{color:#a7b5af;font-size:10px;display:flex;align-items:center;gap:11px}
.live-dot{height:7px;width:7px;border-radius:100%;background:#a6eab7;box-shadow:0 0 11px #8df4a9;animation:beacon 2.2s ease-in-out infinite}
.stamp-divider{color:#51605e}
.icon-button{width:37px;height:37px;border:1px solid var(--line);border-radius:10px;background:#17242b;color:var(--mint);font-size:17px;cursor:pointer;transition:.2s}
.icon-button:hover,.icon-button.sound-on{border-color:#819c74;background:#27382f;box-shadow:0 0 18px #9bdd8620;color:var(--lime)}
.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 326px;gap:25px;padding-top:27px}
.main-column{min-width:0}
.section-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;min-height:60px}
.eyebrow{font-size:9px;color:#a6b69b;margin:0 0 8px;letter-spacing:1.6px}
.eyebrow-divider{color:#637761;padding:0 4px}
.section-heading h1{font:600 clamp(17px,2vw,22px) var(--display);letter-spacing:.5px;margin:0}
.section-heading h1 span{font:11px var(--mono);color:#92a192;vertical-align:3px;margin-left:5px}
.floor-subtitle{margin:4px 0 0;color:#84938d;font-size:11px;letter-spacing:.2px}
.floor-badge{display:flex;align-items:center;gap:6px;color:#8f9e98;font-size:9px;white-space:nowrap}
.floor-badge strong{font:600 16px var(--display);color:var(--lime);margin-left:3px;text-shadow:0 0 14px #c5ee7a55}
.depth-track{height:20px;display:flex;align-items:center;gap:5px;color:#657670;font-size:7px;margin:0 0 9px}
.depth-track i{height:3px;width:33px;border-radius:5px;background:#293638;transition:background .5s,box-shadow .5s}
.depth-track i.active{background:var(--teal);box-shadow:0 0 8px #7ac4b066}
.depth-track i.current{height:5px;background:var(--lime);box-shadow:0 0 12px #d8f48799}
.depth-track span{margin-left:7px}
.game-frame{position:relative;border:1px solid #3c504b;border-radius:12px;background:#111b20;overflow:hidden;box-shadow:0 20px 55px #03080c99,0 0 0 1px #d8f48708,inset 0 0 30px #a4d58808;transition:box-shadow .25s,border-color .25s}
.game-frame:before{content:"";position:absolute;inset:39px 0 39px;z-index:1;pointer-events:none;background:linear-gradient(115deg,#c1ed9b07,transparent 23% 72%,#7bc2b008)}
.map-topline{height:39px;padding:0 16px;display:flex;align-items:center;justify-content:space-between;color:#91a39c;font-size:9px;border-bottom:1px solid #2e403e;background:linear-gradient(90deg,#17252a,#142027 65%,#182522)}
.map-topline>span:first-child{display:flex;gap:8px;align-items:center}
.tiny-square{display:inline-block;width:7px;height:7px;background:var(--lime);box-shadow:0 0 8px #d8f48770}
.map-coords{color:#c3d0be;font-variant-numeric:tabular-nums}
.board{--cols:13;--rows:9;position:relative;display:grid;grid-template-columns:repeat(var(--cols),minmax(0,1fr));grid-template-rows:repeat(var(--rows),min(7.05vw,66px));gap:4px;padding:16px;background-image:radial-gradient(#556b5c 1px,transparent 1px),linear-gradient(140deg,#172529,#121d23 50%,#192521);background-size:22px 22px,100% 100%;isolation:isolate}
.board:before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;opacity:.5;background:radial-gradient(ellipse at 70% 40%,#92c67d12,transparent 42%),radial-gradient(ellipse at 20% 85%,#6aa79d10,transparent 35%)}
.tile{position:relative;display:flex;align-items:center;justify-content:center;border-radius:6px;background:linear-gradient(145deg,#26362f,#202d2b);border:1px solid #34463f;color:#eff4e5;overflow:hidden;transition:background .18s,transform .15s,filter .2s;animation:tileWake .32s both;animation-delay:calc(var(--n,0)*5ms)}
.tile:after{content:"";position:absolute;inset:0;pointer-events:none;opacity:.28;background:linear-gradient(135deg,#d7ffba12,transparent 40%,#03080524)}
.tile.wall{background:linear-gradient(145deg,#24312f,#192421);border-color:#303e38;box-shadow:inset 0 0 13px #09110fbb,0 2px 0 #090f0d;}
.tile.wall:before{content:"";position:absolute;width:60%;height:2px;left:14%;top:32%;background:#55665a55;transform:rotate(-18deg);box-shadow:8px 11px 0 #101b18,18px 20px 0 #50615538}
.tile.floor:nth-child(odd){background:linear-gradient(145deg,#263630,#1e2c29)}
.tile.player-tile{background:radial-gradient(circle at 50% 40%,#4a6b55,#243f3d 72%);border-color:#b9e8a4;box-shadow:inset 0 0 20px #9ce08d38,0 0 17px #9ff0ae35;z-index:2;animation:playerArrival .22s ease-out}
