.tile.item-tile{border-color:#95834c;background:radial-gradient(circle at 50% 40%,#554b31,#302f28 80%);box-shadow:inset 0 0 18px #f4d36a20;animation:lootHover 2.4s ease-in-out infinite}
.tile.exit-tile{border-color:#849956;background:radial-gradient(circle at 50% 45%,#42533a,#29362d);box-shadow:inset 0 0 19px #b4e77d2b,0 0 12px #c5ee7a20;animation:exitGlow 2s infinite}
.tile .sprite{position:relative;z-index:1;font-size:clamp(17px,2.4vw,27px);line-height:1;filter:drop-shadow(0 3px 4px #070a0f);user-select:none;transition:transform .18s}
.tile.enemy-tile .sprite{animation:spriteFloat 2.7s ease-in-out infinite}
.tile.player-tile .sprite{font-size:clamp(18px,2.3vw,26px);filter:drop-shadow(0 2px 5px #b2f3a5aa)}
.tile.item-tile .sprite{color:#f6da7c;font-size:clamp(19px,2.5vw,28px);text-shadow:0 0 12px #ffe69088}
.tile.exit-tile .sprite{color:#d8f487;font-size:clamp(18px,2.3vw,25px);text-shadow:0 0 12px #d8f487aa}
.tile .hp-pip{position:absolute;z-index:2;bottom:4px;left:5px;right:5px;height:4px;border-radius:4px;background:#101512;overflow:hidden;box-shadow:0 1px 3px #000}
.tile .hp-pip i{height:100%;display:block;background:linear-gradient(90deg,#ff776e,#ffc27a);transition:width .25s}
.tile:focus-visible{outline:2px solid var(--lime);outline-offset:1px}
.fx-layer{position:absolute;inset:39px 0 39px;z-index:3;pointer-events:none;overflow:hidden}
.game-toast{position:absolute;z-index:4;top:51px;left:50%;transform:translate(-50%,-8px);padding:7px 12px;border:1px solid #94b78388;border-radius:30px;background:#111bdeea;color:#e5f3d9;font:9px var(--mono);letter-spacing:.7px;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s;white-space:nowrap;box-shadow:0 5px 20px #0008}
.game-toast.show{opacity:1;transform:translate(-50%,0)}
.fx-pop{position:absolute;font:700 15px var(--mono);color:#f5dc8e;text-shadow:0 2px 8px #050907;animation:floatText .85s ease-out forwards}
.fx-particle{position:absolute;width:6px;height:6px;border-radius:50%;background:var(--lime);box-shadow:0 0 11px currentColor;animation:particleBurst .65s ease-out forwards}
.game-frame.hit-flash{animation:frameHit .24s ease-out;border-color:#ff8177}
.game-frame.depth-warp .board{animation:depthWarp .52s cubic-bezier(.2,.8,.2,1)}
.map-footer{height:39px;display:flex;align-items:center;gap:17px;padding:0 16px;color:#a1afa8;font-size:8px;border-top:1px solid #2e403e;background:#142027}
.legend{font-size:11px;margin-right:3px}.player-legend{color:var(--mint)}.enemy-legend{color:var(--coral)}.loot-legend{color:var(--yellow)}.exit-legend{color:var(--lime)}
.turn-counter{margin-left:auto;color:#c2d1bd;font-variant-numeric:tabular-nums}
.controls-row{display:flex;justify-content:space-between;align-items:center;padding:15px 2px}
.action-copy{display:flex;flex-direction:column;gap:4px}.action-copy .eyebrow{margin:0}.action-copy>span:last-child{font-size:12px;color:#c5ccca;transition:color .2s}
.dpad{display:grid;grid-template-columns:36px 36px 36px;grid-template-rows:34px 34px;gap:4px}
.dpad button{border:1px solid #405249;background:linear-gradient(145deg,#24352f,#1b2b2b);border-radius:8px;color:#d4efd0;font-size:18px;cursor:pointer;touch-action:manipulation;transition:transform .12s,background .16s,border-color .16s;box-shadow:0 2px 0 #0b1513}
.dpad button:hover{border-color:#a1c88a;background:#34483a}.dpad button:first-child{grid-column:2}.dpad button:nth-child(2){grid-column:1;grid-row:2}.dpad button:nth-child(3){grid-column:2;grid-row:2}.dpad button:nth-child(4){grid-column:3;grid-row:2}
.dpad button:active,.action-button:active{transform:scale(.94) translateY(1px);background:#344758}
button:focus-visible{outline:2px solid var(--lime);outline-offset:3px}
.sidebar{display:flex;flex-direction:column;gap:12px}
.panel{position:relative;background:linear-gradient(145deg,#19272d,#131f27);border:1px solid #31423f;border-radius:10px;padding:14px 15px;box-shadow:0 8px 22px #03090b32;overflow:hidden}
.panel:before{content:"";position:absolute;top:0;left:15px;right:15px;height:1px;background:linear-gradient(90deg,transparent,#9ac89155,transparent)}
.panel-title{height:17px;display:flex;align-items:center;justify-content:space-between;font-size:9px;color:#bac6bd;letter-spacing:1.2px}
.status-pill{font-size:8px;color:#b6edc4;border:1px solid #496651;padding:3px 6px;border-radius:4px;letter-spacing:.7px;background:#a6eab70c}
.operator-profile{display:flex;align-items:center;gap:11px;margin:14px 0}
.operator-avatar{height:46px;width:46px;border-radius:12px;background:radial-gradient(circle at 35% 25%,#526451,#263936);border:1px solid #627d64;color:var(--lime);font-size:27px;display:grid;place-items:center;box-shadow:inset 0 0 17px #bddf7a16,0 0 15px #8eaf7020}
.operator-profile h2{font:600 13px var(--display);letter-spacing:.7px;margin:0 0 5px}.operator-profile p{font-size:9px;color:#aab8b0;margin:0}.sep{padding:0 4px;color:#66746d}
.stat-line{display:flex;justify-content:space-between;color:#aab8b0;font-size:9px;margin:8px 0}.stat-line strong{color:#eef2e7;font-size:10px;font-weight:500;font-variant-numeric:tabular-nums}
.meter{height:7px;border-radius:8px;background:#0d171a;overflow:hidden;border:1px solid #283731}.meter i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#c8ed98,#77c99f);border-radius:8px;transition:width .35s cubic-bezier(.2,.8,.2,1);box-shadow:0 0 9px #96e5a855}
.resource-line{margin:14px 0 11px}.resource-line span{color:#e2cf95}.resource-line strong{color:var(--yellow)}
.operator-actions{display:grid;gap:7px}
.action-button{height:37px;background:linear-gradient(100deg,#30483c,#263c37);border:1px solid #577364;color:#e0f0d7;border-radius:7px;text-align:left;padding:0 10px;font:500 9px var(--mono);letter-spacing:.6px;cursor:pointer;transition:filter .15s,transform .15s,border-color .15s}
.action-button:hover:not(:disabled){filter:brightness(1.17);border-color:#9cbd85}.action-button>span{color:var(--lime);font-size:16px;vertical-align:-2px;margin-right:7px}.action-button kbd{float:right;color:#c0c6bb;margin-top:3px}.action-button:disabled{opacity:.42;cursor:not-allowed;filter:saturate(.55)}
.action-button.secondary{background:linear-gradient(100deg,#25343a,#1e2b30);border-color:#3a5149;color:#cbd6cc}.action-button.secondary>span{color:#9edba8}.action-button small{float:right;color:#d3dcbf;font:10px var(--mono);margin-top:3px}
.team-panel{padding-bottom:11px}.team-list{display:grid;gap:7px;margin-top:12px}
.team-creature{display:grid;grid-template-columns:39px 1fr auto;align-items:center;gap:9px;padding:8px;background:linear-gradient(115deg,#23332f,#1a292b);border:1px solid #354840;border-radius:8px;animation:cardIn .3s ease-out both;transition:border-color .2s,transform .2s}.team-creature:hover{border-color:#66835f;transform:translateX(2px)}
.creature-avatar{height:38px;width:38px;display:grid;place-items:center;font-size:23px;border-radius:8px;background:radial-gradient(circle,#405442,#293832);border:1px solid #48614a;text-shadow:0 3px 5px #0008}
.creature-info{min-width:0}.creature-info strong{display:block;font:600 11px var(--display);text-transform:uppercase;letter-spacing:.3px}.creature-info small{font:9px var(--mono);color:#a0b0a7}
.creature-vitals{min-width:35px;text-align:right}.creature-hp{font:9px var(--mono);color:#b6e0b6;display:block}.creature-mini-meter{height:3px;margin-top:5px;background:#101a18;border-radius:3px;overflow:hidden}.creature-mini-meter i{height:100%;display:block;background:#9bd49c;border-radius:3px}
.team-note{font-size:10px;line-height:1.5;color:#98a69e;margin:10px 1px 0}
