.modal{position:fixed;inset:0;background:#080e12e8;z-index:10;display:flex;align-items:center;justify-content:center;padding:18px;backdrop-filter:blur(10px);opacity:0;visibility:hidden;transition:opacity .35s,visibility .35s}
.modal.visible{opacity:1;visibility:visible}.modal-card{position:relative;max-width:480px;width:100%;padding:35px 39px 28px;background:linear-gradient(145deg,#22332e,#17262a 68%,#1d2927);border:1px solid #536a4f;border-radius:15px;box-shadow:0 25px 90px #070b13,0 0 50px #c5ed7930;text-align:center;overflow:hidden;transform:translateY(18px) scale(.97);transition:transform .48s cubic-bezier(.2,.8,.2,1)}
.modal.visible .modal-card{transform:translateY(0) scale(1)}
.modal-card:before{content:'';position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 50% 25%,#c9ef9c18,transparent 45%),linear-gradient(120deg,transparent 30%,#e0f5ca06 50%,transparent 70%)}
.modal-kicker{display:flex;gap:9px;justify-content:center;align-items:center;color:#b6c8b3;font-size:9px;letter-spacing:1.4px}
