.hero-sigil:before,.hero-sigil:after{content:"";position:absolute;border:1px solid #a9c78332;border-radius:50%;inset:-9px;animation:sigilOrbit 13s linear infinite}.hero-sigil:after{inset:-17px;border-style:dashed;opacity:.55;animation-direction:reverse;animation-duration:30s}
