@media(max-width:420px){.map-footer{gap:6px;font-size:6px}.map-coords{display:none}.section-heading h1{font-size:15px}.board{gap:2px;padding:7px}.tile .sprite{font-size:18px}.run-stamp{letter-spacing:.4px}.journal-panel{min-height:190px}.depth-track i{width:23px}.depth-track span{font-size:6px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}

