+
+/* 2.5D underwild: layered stone slabs, sculpted terrain and floating field models. */
+.board {
+  perspective: 1100px;
+  perspective-origin: 50% 42%;
+  background-image:
+    radial-gradient(ellipse at 48% 48%, #9fca7d12, transparent 56%),
+    radial-gradient(#60745e 1px, transparent 1px),
+    linear-gradient(145deg, #1a2a2a, #111b22 52%, #1b2923);
+  background-size: auto, 22px 22px, 100% 100%;
+  box-shadow: inset 0 15px 32px #080f12a8, inset 0 -12px 30px #080d0c77;
+}
+.tile {
+  transform-style: preserve-3d;
+  border-radius: 5px;
+  box-shadow: 0 var(--extrusion, 4px) 0 #111b18, 0 calc(var(--extrusion, 4px) + 2px) 7px #05090762, inset 0 1px 0 #d5efbd18;
+  background-image: linear-gradient(145deg, #ffffff08, transparent 48%, #050a0922);
+}
+.tile.floor {
+  background-image:
+    radial-gradient(ellipse at 48% 82%, #080f0d48, transparent 52%),
+    linear-gradient(145deg, #33443a, #263831 48%, #1c2b29);
+  border-color: #3d5147;
+  box-shadow: 0 var(--extrusion, 4px) 0 #14211d, 0 calc(var(--extrusion, 4px) + 2px) 7px #05090762, inset 0 1px 0 #c6e7ad20, inset 0 -8px 12px #0b151229;
+}
+.tile.floor:nth-child(odd) {
+  background-image:
+    radial-gradient(ellipse at 48% 82%, #080f0d48, transparent 52%),
+    linear-gradient(145deg, #304138, #25352f 48%, #1b2927);
+}
+.tile.wall {
+  background-image:
+    linear-gradient(155deg, #64746444 0 2%, transparent 20%),
+    linear-gradient(35deg, transparent 53%, #101a17aa 54% 57%, transparent 58%),
+    linear-gradient(145deg, #34413b, #24312e 56%, #182421);
+  border-color: #405047;
+  box-shadow: 0 var(--extrusion, 4px) 0 #111a17, 0 calc(var(--extrusion, 4px) + 3px) 8px #0308078c, inset 0 2px 0 #a6b69b22, inset 0 -11px 13px #09110f99;
+}
+.tile.wall:before {
+  width: 63%; height: 3px; left: 13%; top: 29%;
+  background: linear-gradient(90deg, #74837188, #53635555 68%, transparent);
+  transform: rotate(-18deg);
+  box-shadow: 8px 11px 0 -1px #111c18, 18px 20px 0 0 #65736555, 2px 3px 0 #a2b19733;
+}
+.tile:after {
+  opacity: .48;
+  background: linear-gradient(135deg, #e1f4ca19, transparent 38% 70%, #03080638);
+}
+.tile.player-tile {
+  background-image: radial-gradient(ellipse at 50% 80%, #080e0c88, transparent 56%), radial-gradient(circle at 50% 34%, #658268, #304e45 72%);
+  box-shadow: 0 var(--extrusion, 4px) 0 #1b322b, 0 calc(var(--extrusion, 4px) + 3px) 12px #020706aa, inset 0 1px 0 #e1ffd166, inset 0 0 20px #9ce08d38, 0 0 19px #9ff0ae40;
+}
+.tile.player-tile .sprite,
+.tile.enemy-tile .sprite,
+.tile.item-tile .sprite,
+.tile.exit-tile .sprite {
+  transform: translateY(-4px) translateZ(8px) scale(1.05);
+  filter: drop-shadow(0 2px 0 #101713) drop-shadow(0 6px 4px #030806b8);
+}
+.tile.player-tile .sprite { filter: drop-shadow(0 2px 0 #26382c) drop-shadow(0 5px 5px #b2f3a5a8); }
+.tile.enemy-tile {
+  background-image: radial-gradient(ellipse at 50% 82%, #080b0bcc, transparent 55%), radial-gradient(circle at 50% 38%, #684b44, #342c2c 76%);
+  box-shadow: 0 var(--extrusion, 4px) 0 #211d1c, 0 calc(var(--extrusion, 4px) + 3px) 10px #030606aa, inset 0 1px 0 #ffc1a526, inset 0 0 16px #ff806b19;
+}
+.tile.enemy-tile.boss-tile {
+  background-image: radial-gradient(ellipse at 50% 84%, #070909dd, transparent 56%), radial-gradient(circle at 50% 36%, #86524a, #382729 76%);
+  box-shadow: 0 var(--extrusion, 4px) 0 #291b1c, 0 calc(var(--extrusion, 4px) + 4px) 13px #030606c9, inset 0 2px 0 #ffb09b55, inset 0 0 22px #ff725e55, 0 0 15px #ff725e35;
+}
+.tile.item-tile {
+  background-image: radial-gradient(ellipse at 50% 82%, #080b09b8, transparent 55%), radial-gradient(circle at 50% 40%, #665a39, #343229 80%);
+  box-shadow: 0 var(--extrusion, 4px) 0 #29251b, 0 calc(var(--extrusion, 4px) + 3px) 10px #030606a8, inset 0 1px 0 #fff0b044, inset 0 0 18px #f4d36a2a;
+}
+.tile.exit-tile {
+  background-image: radial-gradient(ellipse at 50% 82%, #080c09bb, transparent 57%), radial-gradient(circle at 50% 45%, #526840, #29372d 77%);
+  box-shadow: 0 var(--extrusion, 4px) 0 #202b1d, 0 calc(var(--extrusion, 4px) + 3px) 11px #030606a8, inset 0 2px 0 #e3f7b466, inset 0 0 19px #b4e77d40, 0 0 12px #c5ee7a29;
+}
+.tile .hp-pip { transform: translateZ(9px); }
+.game-frame { box-shadow: 0 24px 60px #020609aa, 0 0 0 1px #d8f4870c, inset 0 0 38px #a4d5880c; }
+@media (max-width: 680px) {
+  .board { perspective: 800px; perspective-origin: 50% 45%; }
+  .tile { box-shadow: 0 var(--extrusion, 4px) 0 #111b18, 0 calc(var(--extrusion, 4px) + 1px) 4px #05090770, inset 0 1px 0 #d5efbd18; }
+}

